#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import readline from 'readline';
import { spawn } from 'child_process';
import crypto from 'crypto';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const root = process.cwd();
const CONFIG_FILENAME = 'ngx-locatorjs.config.json';
const PROXY_FILENAME = 'ngx-locatorjs.proxy.cjs';
// Marks proxy modules generated by this tool, so only those are ever overwritten.
const PROXY_MARKER = 'Generated by ngx-locatorjs (locatorjs-config).';
const ANSI_ENABLED = Boolean(process.stdout.isTTY);
const IGNORED_SCAN_DIR_NAMES = new Set([
  'node_modules',
  'dist',
  'coverage',
  '.angular',
  '.git',
  '.nx',
  '.turbo',
  '.cache',
  'build',
  'out',
  'tmp',
]);

type AngularServeConfig = {
  proxyConfig?: string;
};

type AngularServeTarget = {
  options?: AngularServeConfig;
  configurations?: Record<string, AngularServeConfig>;
};

type AngularProject = {
  root?: string;
  sourceRoot?: string;
  architect?: {
    serve?: AngularServeTarget;
  };
  targets?: {
    serve?: AngularServeTarget;
  };
};

type AngularJson = {
  projects?: Record<string, AngularProject>;
};

const configPath = path.resolve(root, CONFIG_FILENAME);
const proxyConfigPath = resolveProxyConfigPath();

console.log('🚀 LocatorJs (Open-in-Editor) Configuration Setup\n');

if (fs.existsSync(configPath)) {
  console.log(`⚠️  ${CONFIG_FILENAME} already exists!`);

  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  rl.question('Do you want to overwrite it? (y/N): ', (answer) => {
    rl.close();
    if (answer.toLowerCase() !== 'y' && answer.toLowerCase() !== 'yes') {
      console.log('Setup cancelled.');
      process.exit(0);
    }
    startSetup();
  });
} else {
  startSetup();
}

async function startSetup() {
  try {
    logDefaults();
    const authToken = generateAuthToken();
    const config = {
      port: 4123,
      host: '127.0.0.1',
      workspaceRoot: '.',
      editor: await selectEditor(),
      fallbackEditor: 'code',
      authToken,
      scan: await promptScanSettings(),
    };

    fs.writeFileSync(configPath, JSON.stringify(config, null, 2));

    fs.writeFileSync(proxyConfigPath, buildDynamicProxyModule());

    console.log('\n✅ Configuration saved successfully!');
    console.log(`📁 Config: ${path.relative(root, configPath)}`);
    console.log(`🔗 Proxy: ${path.relative(root, proxyConfigPath)} (dynamic from config port)`);
    console.log('🔒 Request auth token generated and wired into proxy headers');

    ensureGitignoreEntries(['.open-in-editor/']);

    console.log('\n🔍 Running component scan...');
    const scanScript = path.resolve(__dirname, 'cmp-scan.js');
    if (fs.existsSync(scanScript)) {
      try {
        const scanProcess = spawn(process.execPath, [scanScript], {
          stdio: 'inherit',
          cwd: root,
        });

        scanProcess.on('close', (code) => {
          if (code === 0) {
            console.log('\n✅ Component scan completed!');
            printNextSteps(proxyConfigPath);
          } else {
            console.log('\n⚠️  Component scan failed, but config is saved.');
            printManualScan(proxyConfigPath);
          }
        });
      } catch {
        console.log('\n⚠️  Could not run component scan automatically.');
        printManualScan(proxyConfigPath);
      }
    } else {
      console.log('\n⚠️  scan script not found.');
      printManualScan(proxyConfigPath);
    }
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    console.error('\n❌ Setup failed:', message);
    process.exit(1);
  }
}

function printManualScan(proxyPath: string) {
  console.log('Please run it manually: npx locatorjs-scan');
  printNextSteps(proxyPath);
}

function printNextSteps(proxyPath: string) {
  console.log('\n🚀 Next steps:');
  console.log('   npx locatorjs-open-in-editor');
  console.log(
    `   (run your Angular dev server with --proxy-config ${path.relative(root, proxyPath)})`,
  );
}

function buildDynamicProxyModule(): string {
  return `'use strict';
// ${PROXY_MARKER}

const fs = require('fs');
const path = require('path');

function loadLocatorConfig() {
  const configPath = path.resolve(process.cwd(), '${CONFIG_FILENAME}');
  try {
    return JSON.parse(fs.readFileSync(configPath, 'utf8'));
  } catch {
    return {};
  }
}

const cfg = loadLocatorConfig();
const host = typeof cfg.host === 'string' && cfg.host.trim() ? cfg.host.trim() : '127.0.0.1';
const port = Number(process.env.OPEN_IN_EDITOR_PORT || cfg.port || 4123);
const authToken = typeof cfg.authToken === 'string' ? cfg.authToken : '';
const headers = authToken ? { 'x-locatorjs-token': authToken } : {};
const target = \`http://\${host}:\${port}\`;

module.exports = {
  '/__open-in-editor': {
    target,
    secure: false,
    changeOrigin: true,
    headers,
  },
  '/__open-in-editor-search': {
    target,
    secure: false,
    changeOrigin: true,
    headers,
  },
  '/__cmp-map': {
    target,
    secure: false,
    changeOrigin: true,
    headers,
  },
};
`;
}

function resolveProxyConfigPath(): string {
  const angularProxyPath = findProxyConfigFromAngularJson();
  if (angularProxyPath) {
    const ext = path.extname(angularProxyPath).toLowerCase();
    if (ext === '.js' || ext === '.cjs') {
      if (!fs.existsSync(angularProxyPath) || isGeneratedProxyModule(angularProxyPath)) {
        return angularProxyPath;
      }
      console.log(
        `⚠️  angular.json points to an existing proxy (${path.relative(root, angularProxyPath)}). It will not be modified.`,
      );
      console.log(
        `   Creating ${PROXY_FILENAME} instead. Merge its entries into your proxy config to enable the locator endpoints.`,
      );
      return path.resolve(root, PROXY_FILENAME);
    }
    if (ext === '.json') {
      console.log(`⚠️  angular.json points to JSON proxy (${path.basename(angularProxyPath)}).`);
      console.log(
        `   Creating dynamic proxy module ${PROXY_FILENAME} instead. Update angular.json proxyConfig to use it for single-source port management.`,
      );
      return path.resolve(root, PROXY_FILENAME);
    }
    console.log(
      `⚠️  Unsupported proxy extension (${path.basename(angularProxyPath)}). Creating ${PROXY_FILENAME} instead.`,
    );
    return path.resolve(root, PROXY_FILENAME);
  }

  return path.resolve(root, PROXY_FILENAME);
}

function isGeneratedProxyModule(filePath: string): boolean {
  try {
    return fs.readFileSync(filePath, 'utf8').includes(PROXY_MARKER);
  } catch {
    return false;
  }
}

function findProxyConfigFromAngularJson(): string | null {
  const angularJsonPath = path.resolve(root, 'angular.json');
  if (!fs.existsSync(angularJsonPath)) return null;

  try {
    const angularJson = JSON.parse(fs.readFileSync(angularJsonPath, 'utf8')) as AngularJson;
    const projects = angularJson?.projects ?? {};

    for (const project of Object.values(projects)) {
      const targets = project.architect || project.targets;
      const serve = targets?.serve;
      if (!serve) continue;

      const direct = serve?.options?.proxyConfig;
      if (typeof direct === 'string' && direct.trim().length > 0) {
        return path.resolve(root, direct);
      }

      const configurations = serve?.configurations;
      if (configurations && typeof configurations === 'object') {
        for (const config of Object.values(configurations)) {
          const confProxy = config?.proxyConfig;
          if (typeof confProxy === 'string' && confProxy.trim().length > 0) {
            return path.resolve(root, confProxy);
          }
        }
      }
    }
  } catch {
    // ignore parse errors
  }

  return null;
}

function ensureGitignoreEntries(entries: string[]) {
  const gitignorePath = path.resolve(root, '.gitignore');
  if (!fs.existsSync(gitignorePath)) return;

  const content = fs.readFileSync(gitignorePath, 'utf8');
  const lines = content.split(/\r?\n/);
  const missing = entries.filter((entry) => !lines.includes(entry));
  if (missing.length === 0) return;

  const suffix = content.endsWith('\n') ? '' : '\n';
  const block = `${suffix}# ngx-locatorjs\n${missing.join('\n')}\n`;
  fs.appendFileSync(gitignorePath, block);
  console.log(`🧹 Added to .gitignore: ${missing.join(', ')}`);
}

function logDefaults() {
  console.log('⚙️  Defaults applied:');
  console.log('   → Port: 4123');
  console.log('   → Host: 127.0.0.1');
  console.log('   → Workspace root: .');
}

function generateAuthToken(): string {
  return crypto.randomBytes(24).toString('hex');
}

function selectEditor(): Promise<string> {
  const availableEditors = [
    { name: 'Cursor', value: 'cursor' },
    { name: 'Zed', value: 'zed' },
    { name: 'Antigravity IDE', value: 'antigravity' },
    { name: 'VS Code', value: 'code' },
    { name: 'WebStorm', value: 'webstorm' },
  ];

  if (!process.stdin.isTTY || typeof process.stdin.setRawMode !== 'function') {
    console.log('\n🎯 Please select your editor:');
    availableEditors.forEach((editor, index) => {
      console.log(`   ${index + 1}. ${editor.name}`);
    });

    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
    });

    return new Promise((resolve) => {
      rl.question('\nEnter number (1-5, default: 1 for Cursor): ', (answer) => {
        rl.close();
        const choice = parseInt(answer.trim(), 10) || 1;
        const selected =
          availableEditors[Math.max(0, Math.min(choice - 1, availableEditors.length - 1))];
        console.log(`   → Selected: ${selected.name}`);
        resolve(selected.value);
      });
    });
  }

  let selectedIndex = 0;

  const renderMenu = () => {
    console.clear();
    console.log('\n🎯 Please select your editor:');
    console.log('   Use ↑↓ to navigate, Enter to select (default: Cursor)\n');

    availableEditors.forEach((editor, index) => {
      const isSelected = index === selectedIndex;
      const pointer = isSelected ? '▶' : ' ';
      const highlight = isSelected ? '\x1b[36m' : '';
      const reset = isSelected ? '\x1b[0m' : '';
      console.log(`${highlight}${pointer} ${editor.name}${reset}`);
    });
  };

  return new Promise((resolve) => {
    process.stdin.setRawMode(true);
    process.stdin.resume();
    process.stdin.setEncoding('utf8');

    renderMenu();

    const handleKeypress = (key: string) => {
      switch (key) {
        case '\u001b[A':
          selectedIndex = selectedIndex > 0 ? selectedIndex - 1 : availableEditors.length - 1;
          renderMenu();
          break;
        case '\u001b[B':
          selectedIndex = selectedIndex < availableEditors.length - 1 ? selectedIndex + 1 : 0;
          renderMenu();
          break;
        case '\r':
        case '\n': {
          process.stdin.setRawMode(false);
          process.stdin.pause();
          process.stdin.removeListener('data', handleKeypress);

          const selected = availableEditors[selectedIndex];
          console.log(`\n✨ Selected: ${selected.name}`);
          resolve(selected.value);
          break;
        }
        case '\u0003':
          console.log('\n\nCancelled. Setting Cursor as default.');
          process.stdin.setRawMode(false);
          process.stdin.pause();
          resolve('cursor');
          break;
      }
    };

    process.stdin.on('data', handleKeypress);
  });
}

async function promptScanSettings() {
  const defaultInclude = [
    'src/**/*.{ts,tsx,js,jsx}',
    'projects/**/*.{ts,tsx,js,jsx}',
    'apps/**/*.{ts,tsx,js,jsx}',
    'libs/**/*.{ts,tsx,js,jsx}',
  ];
  const defaultExclude = [
    '**/node_modules/**',
    '**/dist/**',
    '**/.angular/**',
    '**/coverage/**',
    '**/*.spec.{ts,tsx,js,jsx}',
    '**/*.test.{ts,tsx,js,jsx}',
    '**/*.e2e.{ts,tsx,js,jsx}',
  ];

  const includeGlobs = detectIncludeGlobs(defaultInclude);
  const excludeGlobs = detectExcludeGlobs(defaultExclude);
  printScanSettingsSummary(includeGlobs, excludeGlobs);

  return {
    includeGlobs: includeGlobs.values,
    excludeGlobs: excludeGlobs.values,
  };
}

type IncludeDetectionResult = {
  values: string[];
  autoDetected: boolean;
  sources: string[];
};

type ExcludeDetectionResult = {
  values: string[];
  autoDetected: boolean;
  sources: string[];
};

function detectIncludeGlobs(defaultInclude: string[]): IncludeDetectionResult {
  const sources: string[] = [];
  let detectedBaseDirs = detectIncludeBaseDirsFromAngularJson();

  if (detectedBaseDirs.size > 0) {
    sources.push('angular.json');

    const supplemental = detectSupplementalWorkspaceBaseDirs(detectedBaseDirs);
    if (supplemental.size > 0) {
      supplemental.forEach((dir) => detectedBaseDirs.add(dir));
      sources.push('workspace directories (not declared in angular.json)');
    }
  } else {
    detectedBaseDirs = detectIncludeBaseDirsFromConventionalLayout();
    if (detectedBaseDirs.size > 0) {
      sources.push('existing directories');
    }
  }

  if (detectedBaseDirs.size > 0) {
    return {
      values: toGlobPatterns(detectedBaseDirs),
      autoDetected: true,
      sources,
    };
  }

  return {
    values: defaultInclude,
    autoDetected: false,
    sources: [],
  };
}

function detectExcludeGlobs(defaultExclude: string[]): ExcludeDetectionResult {
  const extraExcludeCandidates: Array<{ pattern: string; reason: string; when: boolean }> = [
    { pattern: '**/.nx/**', reason: 'nx.json', when: fileExists('nx.json') },
    { pattern: '**/.turbo/**', reason: 'turbo.json', when: fileExists('turbo.json') },
    { pattern: '**/.cache/**', reason: '.cache directory', when: directoryExists('.cache') },
    { pattern: '**/build/**', reason: 'build directory', when: directoryExists('build') },
    { pattern: '**/out/**', reason: 'out directory', when: directoryExists('out') },
    { pattern: '**/tmp/**', reason: 'tmp directory', when: directoryExists('tmp') },
  ];

  const values = [...defaultExclude];
  const reasons: string[] = [];

  for (const candidate of extraExcludeCandidates) {
    if (!candidate.when) continue;
    if (!values.includes(candidate.pattern)) {
      values.push(candidate.pattern);
      reasons.push(`${candidate.pattern} (${candidate.reason})`);
    }
  }

  return {
    values,
    autoDetected: reasons.length > 0,
    sources: reasons,
  };
}

function detectIncludeBaseDirsFromAngularJson(): Set<string> {
  const angularJsonPath = path.resolve(root, 'angular.json');
  if (!fs.existsSync(angularJsonPath)) return new Set<string>();

  try {
    const angularJson = JSON.parse(fs.readFileSync(angularJsonPath, 'utf8')) as AngularJson;
    const projects = angularJson?.projects ?? {};
    const detectedBaseDirs = new Set<string>();

    for (const project of Object.values(projects)) {
      const sourceRoot = normalizeRelativePath(project.sourceRoot);
      const projectRoot = normalizeRelativePath(project.root);

      if (sourceRoot && directoryExists(sourceRoot)) {
        detectedBaseDirs.add(sourceRoot);
        continue;
      }

      if (!projectRoot) continue;

      const srcUnderProjectRoot = normalizeRelativePath(path.posix.join(projectRoot, 'src'));
      if (srcUnderProjectRoot && directoryExists(srcUnderProjectRoot)) {
        detectedBaseDirs.add(srcUnderProjectRoot);
      } else if (directoryExists(projectRoot)) {
        detectedBaseDirs.add(projectRoot);
      }
    }

    return detectedBaseDirs;
  } catch {
    return new Set<string>();
  }
}

function detectIncludeBaseDirsFromConventionalLayout(): Set<string> {
  const conventionalDirs = ['src', 'projects', 'apps', 'libs'];
  const detectedBaseDirs = new Set<string>();

  for (const dir of conventionalDirs) {
    if (directoryExists(dir)) {
      detectedBaseDirs.add(dir);
    }
  }

  return detectedBaseDirs;
}

function detectSupplementalWorkspaceBaseDirs(knownBaseDirs: Set<string>): Set<string> {
  const roots = ['projects', 'apps', 'libs'];
  const supplemental = new Set<string>();

  for (const rootDir of roots) {
    const rootPath = path.resolve(root, rootDir);
    if (!directoryExists(rootDir)) continue;

    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(rootPath, { withFileTypes: true });
    } catch {
      continue;
    }

    for (const entry of entries) {
      if (!entry.isDirectory()) continue;
      const candidate = normalizeRelativePath(path.posix.join(rootDir, entry.name));
      if (!candidate) continue;
      if (isCoveredByKnownBaseDirs(candidate, knownBaseDirs)) continue;
      if (!directoryContainsScanCandidateFiles(candidate)) continue;
      supplemental.add(candidate);
    }
  }

  return supplemental;
}

function isCoveredByKnownBaseDirs(candidate: string, knownBaseDirs: Set<string>): boolean {
  for (const known of knownBaseDirs) {
    if (candidate === known) return true;
    if (candidate.startsWith(`${known}/`)) return true;
    if (known.startsWith(`${candidate}/`)) return true;
  }
  return false;
}

function directoryContainsScanCandidateFiles(relPath: string, maxDepth = 6): boolean {
  const absolute = path.resolve(root, relPath);
  return directoryContainsScanCandidateFilesRecursive(absolute, 0, maxDepth);
}

function directoryContainsScanCandidateFilesRecursive(
  absolutePath: string,
  currentDepth: number,
  maxDepth: number,
): boolean {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(absolutePath, { withFileTypes: true });
  } catch {
    return false;
  }

  for (const entry of entries) {
    if (entry.isFile() && /\.(ts|tsx|js|jsx)$/.test(entry.name)) {
      return true;
    }

    if (!entry.isDirectory()) continue;
    if (currentDepth >= maxDepth) continue;
    if (IGNORED_SCAN_DIR_NAMES.has(entry.name)) continue;

    const childPath = path.join(absolutePath, entry.name);
    if (directoryContainsScanCandidateFilesRecursive(childPath, currentDepth + 1, maxDepth)) {
      return true;
    }
  }

  return false;
}

function toGlobPatterns(baseDirs: Set<string>): string[] {
  if (baseDirs.size === 0) return [];

  const preferredOrder = ['src', 'projects', 'apps', 'libs'];

  return Array.from(baseDirs)
    .sort((a, b) => {
      const aIdx = preferredOrder.indexOf(a);
      const bIdx = preferredOrder.indexOf(b);
      const aRank = aIdx === -1 ? Number.MAX_SAFE_INTEGER : aIdx;
      const bRank = bIdx === -1 ? Number.MAX_SAFE_INTEGER : bIdx;
      if (aRank !== bRank) return aRank - bRank;
      return a.localeCompare(b);
    })
    .map((baseDir) => `${baseDir}/**/*.{ts,tsx,js,jsx}`);
}

function normalizeRelativePath(value: string | undefined): string | null {
  if (!value) return null;
  const normalized = value
    .trim()
    .replace(/\\/g, '/')
    .replace(/^\.\/+/, '')
    .replace(/^\/+/, '')
    .replace(/\/+$/, '');
  return normalized.length > 0 ? normalized : null;
}

function directoryExists(relPath: string): boolean {
  try {
    const stat = fs.statSync(path.resolve(root, relPath));
    return stat.isDirectory();
  } catch {
    return false;
  }
}

function fileExists(relPath: string): boolean {
  try {
    const stat = fs.statSync(path.resolve(root, relPath));
    return stat.isFile();
  } catch {
    return false;
  }
}

function colorize(text: string, code: string): string {
  if (!ANSI_ENABLED) return text;
  return `\x1b[${code}m${text}\x1b[0m`;
}

function bold(text: string): string {
  return colorize(text, '1');
}

function cyan(text: string): string {
  return colorize(text, '36');
}

function green(text: string): string {
  return colorize(text, '32');
}

function yellow(text: string): string {
  return colorize(text, '33');
}

function dim(text: string): string {
  return colorize(text, '2');
}

function printScanSettingsSummary(
  includeGlobs: IncludeDetectionResult,
  excludeGlobs: ExcludeDetectionResult,
) {
  const mode = includeGlobs.autoDetected ? 'AUTO-DETECTED' : 'DEFAULTS';
  console.log(`\n${bold(cyan('Scan Settings Applied'))} ${dim(`[${mode}]`)}`);
  console.log(dim('────────────────────────────────────────────'));

  console.log(`${bold(green('Include globs'))}:`);
  includeGlobs.values.forEach((value) => {
    console.log(`  ${green('•')} ${value}`);
  });

  console.log(`\n${bold(yellow('Exclude globs'))}:`);
  excludeGlobs.values.forEach((value) => {
    console.log(`  ${yellow('•')} ${value}`);
  });

  if (includeGlobs.autoDetected) {
    console.log(`\n${bold('Detected from')}: ${includeGlobs.sources.join(', ')}`);
  }
  if (excludeGlobs.autoDetected) {
    console.log(`${bold('Auto-added excludes')}:`);
    excludeGlobs.sources.forEach((value) => {
      console.log(`  ${yellow('•')} ${value}`);
    });
  }

  console.log(`\n${dim(`Edit scan globs anytime in ${CONFIG_FILENAME}`)}`);
}
